import{_ as t,o as r,c as a,ak as n}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse('{"title":"A–Z lesson and quiz source pack for GDD comparison","description":"Status: Source and assessment-seed reference, originally drafted October 28, 2026.\\nUse the current lesson-collection GDD for the 39 individual lessons, prerequisite order, nin","frontmatter":{"title":"A–Z lesson and quiz source pack for GDD comparison","description":"Status: Source and assessment-seed reference, originally drafted October 28, 2026.\\nUse the current lesson-collection GDD for the 39 individual lessons, prerequisite order, nin","source":"docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-complete-lesson-quiz-source-draft.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-complete-lesson-quiz-source-draft.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-complete-lesson-quiz-source-draft.md"}'),s={name:"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-complete-lesson-quiz-source-draft.md"};function o(i,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<div><h1 id="az-lesson-and-quiz-source-pack-for-gdd-comparison">A–Z lesson and quiz source pack for GDD comparison<a class="header-anchor" href="#az-lesson-and-quiz-source-pack-for-gdd-comparison" aria-label="Link to this section">​</a></h1><p><strong>Status:</strong> Source and assessment-seed reference, originally drafted October 28, 2026. Use the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current lesson-collection GDD</a> for the 39 individual lessons, prerequisite order, nine minigames, panel drafts, and four-choice question bank. The older grouped sequence and delivery assumptions below are historical proposals, not current gameplay requirements. This pack is not a replacement for the source book, educator validation, or evidence of implementation. Current work is documentation and preparation only; development requires final owner approval.</p><h2 id="what-complete-means-here">What “complete” means here<a class="header-anchor" href="#what-complete-means-here" aria-label="Link to this section">​</a></h2><ul><li>All <strong>26 original A–Z headings remain unchanged</strong>, with their exact book page locators and one draft learning check each. The <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html">book contents inventory</a> records all 43 PDF pages, including the glossary and safety supplements; it is the source for the original terms below. This pack paraphrases it and does not reproduce its illustrated chapter text.</li><li>The agreed <strong>13 Web3 / 13 Blockchain primary placements</strong> follow the earlier <a href="/Chainy-Docs/content/docs/planning/a-z-lesson-grouping-draft.html">grouping draft</a>. Placement is a teaching choice; the original book calls the entire collection Web3.</li><li>The <strong>13 AI terms</strong> are additions, paired with 13 existing letter slots as requested. They do not replace the book terms. Each AI item points to a primary source; the <a href="/Chainy-Docs/content/docs/planning/ai-source-research.html">research note</a> explains the source choices.</li><li>Every term has a plain-language meaning, an observable learner check, an answer and a reason. These are <strong>question seeds</strong>, not a validated item bank. Two-choice questions are shown for readability; final questions should use a fresh example and avoid answer patterns that permit guessing.</li><li>The proposed play order is <strong>conceptual, not alphabetical</strong>. Five short lessons per world group related terms. This is a recommendation arising from the later discussion, while the baseline still records the earlier 26 individual-letter direction. No decision to replace that direction has been recorded.</li></ul><p><strong>Source limit:</strong> The repository contains the book&#39;s detailed contents inventory, but no original encyclopedia PDF. The original-term explanations below are based on that inventory&#39;s chapter summaries. Check exact nuance, visuals, and permission to reuse any book wording against the PDF before final authoring. This pack is sufficient for a GDD coverage comparison, but it is not a transcription of the 26 chapters.</p><h2 id="source-and-accuracy-rules">Source and accuracy rules<a class="header-anchor" href="#source-and-accuracy-rules" aria-label="Link to this section">​</a></h2><p>Use fictional records, accounts and messages. Do not ask children to use an exchange, scan a live QR code, enter a key or seed phrase, invest, or connect a real wallet. A shared or linked record can reveal a mismatch against a trusted reference; the game does not prove that its fictional transaction really occurred. A token or NFT record does not automatically establish copyright or financial value. A scripted AI response is a simulation; claim training only if the device actually fits a model from examples. The full AI subject can be taught conceptually even if the optional classifier is not in the beta.</p><p>Accuracy cross-checks: <a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST IR 8202 on blockchain</a>, <a href="https://ethereum.org/wallets/">Ethereum on wallets</a>, <a href="https://ethereum.org/developers/docs/smart-contracts/">Ethereum on smart contracts</a>, <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google on supervised learning</a>, and <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google on separating data for evaluation</a>. The book&#39;s “cannot be changed” and “wallet holds tokens” analogies need the qualified explanations above in final game copy.</p><h2 id="recommended-lesson-order-and-gdd-fit">Recommended lesson order and GDD fit<a class="header-anchor" href="#recommended-lesson-order-and-gdd-fit" aria-label="Link to this section">​</a></h2><p>Each lesson has a short explanation, an inspect/choose action, feedback and a fresh check. A “mini-game” is one bounded interaction that can serve several terms; it does not mean a separate system for each letter. The 15-lesson sequence below is <strong>full-curriculum architecture</strong>, not a schedule or a claim that 15 levels can fit the simplified GDD&#39;s three 8–12 minute worlds.</p><table><thead><tr><th>Order</th><th>World lesson and prerequisite</th><th>Original source letters / AI letters</th><th>Suggested action and check</th><th>Fit with simplified GDD</th></tr></thead><tbody><tr><td>W1</td><td>Money and kinds of coins</td><td>F, C, A</td><td>Compare cash, cryptocurrency and different coins; quiz.</td><td>Supports transaction beat.</td></tr><tr><td>W2</td><td>Account access and identity</td><td>W, I, Q</td><td><strong>One Web3 mini-game:</strong> sort fictional actions as safe/unsafe; fresh key/privacy question.</td><td>Expands address station and Safe or Unsafe.</td></tr><tr><td>W3</td><td>Where assets are traded</td><td>E, J, X</td><td>Identify an exchange, a named swap service and a named coin; awareness quiz.</td><td>Reference or later content beyond three beats.</td></tr><tr><td>W4</td><td>Claims and price risk</td><td>H, V, R</td><td>Find an urgency claim and explain why slang/price movement is no guarantee; quiz.</td><td>Extends safety beat.</td></tr><tr><td>W5</td><td>Safety synthesis</td><td>U</td><td>Decide the next safe action in a new message; quiz.</td><td>Could be the world review.</td></tr><tr><td>B1</td><td>Shared linked records</td><td>B, L, D</td><td><strong>One Blockchain mini-game:</strong> order three records, compare a trusted copy, explain mismatch.</td><td>Matches Build the Chain.</td></tr><tr><td>B2</td><td>Authorization and record location</td><td>K, G, O</td><td>Sort shareable/secret information, fee/price, and recorded/not recorded; quiz.</td><td>Adds depth to the reference purchase.</td></tr><tr><td>B3</td><td>Units, unique items and conditions</td><td>T, N, S</td><td>Inspect Lantern #014 and predict an explicit rule&#39;s result; quiz.</td><td>Beyond simplified Blockchain beats.</td></tr><tr><td>B4</td><td>Network checking</td><td>M, P</td><td>Compare simplified work/stake systems and participants; quiz.</td><td>Reference or later content, not simulated consensus.</td></tr><tr><td>B5</td><td>Public information and proofs</td><td>Y, Z</td><td>Choose what a proof discloses and what a public record exposes; quiz.</td><td>Later concept depth.</td></tr><tr><td>A1</td><td>What AI learns from</td><td>A, D, L</td><td>Identify a task, dataset and example labels; quiz.</td><td>Matches example beat.</td></tr><tr><td>A2</td><td>Choosing inputs and fitting</td><td>F, T, M</td><td>Begin <strong>one AI mini-game:</strong> label fictional cards, choose meaningful fields and fit a small model <strong>only if implemented</strong>.</td><td>Matches first half of Teach and Check the Bot.</td></tr><tr><td>A3</td><td>Predicting and checking</td><td>C, P, V</td><td>Continue the same activity on unseen cases; correct a mistake and take a fresh check.</td><td>Matches pattern and review beats.</td></tr><tr><td>A4</td><td>Fairness and human control</td><td>B, R, H</td><td>Inspect missing examples and require a human decision; quiz.</td><td>Extends review beat.</td></tr><tr><td>A5</td><td>Generated content</td><td>G</td><td>Check an authored example of generated text against a supplied fact; quiz.</td><td>Reference or later content; no live generator.</td></tr></tbody></table><p><strong>Sequence dependency:</strong> Web3 introduces a fictional transaction; Blockchain examines its record; AI judges an example request using supplied data. A learner may see a term before its primary lesson, with the formal explanation later. The A–Z encyclopedia remains a searchable reference. Completed lessons can be revisited without forcing A–Z progression.</p><h2 id="original-source-terms-web3-primary-world-1313">Original source terms: Web3 primary world (13/13)<a class="header-anchor" href="#original-source-terms-web3-primary-world-1313" aria-label="Link to this section">​</a></h2><p>The <code>PDF p.</code> locators below refer to the 43-page <em>Web3 Young Learners Encyclopedia</em>. The exact source headings are retained. The check shown after each heading is a <strong>draft sample item</strong>.</p><table><thead><tr><th>Letter / source</th><th>Teaching point</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td><strong>A — Altcoins</strong> (PDF p. 8)</td><td>Coins other than Bitcoin can have different intended uses. A name alone says little about safety or value.</td><td>“Are all digital coins Bitcoin?” <strong>No.</strong> Other coins exist; investigate what a named coin is for.</td></tr><tr><td><strong>C — Cryptocurrency</strong> (p. 10)</td><td>A digital asset used for exchange on a cryptographic network; it is not the same as government-issued money.</td><td>“Is the fictional 12-coin game reward the learner&#39;s real cash?” <strong>No.</strong> Game examples teach concepts without a real financial asset.</td></tr><tr><td><strong>E — Exchanges (Know What, Not How)</strong> (p. 12)</td><td>An exchange is a service where people trade digital assets. Recognition is enough for this course.</td><td>“A website offers to swap one coin for another. Is it an exchange or a wallet backup?” <strong>Exchange.</strong> Trading and credential recovery are different tasks.</td></tr><tr><td><strong>F — Fiat Currency</strong> (p. 13)</td><td>Government-issued money, including cash and ordinary account balances.</td><td>“Which is fiat: pesos in a bank account or the island&#39;s fictional token?” <strong>Pesos.</strong> Digital display does not make ordinary money cryptocurrency.</td></tr><tr><td><strong>H — HODL</strong> (p. 15)</td><td>Slang for holding a cryptocurrency; it is not a reliable investment rule.</td><td>“A post says ‘HODL means a price must rise.’ Is that supported?” <strong>No.</strong> Slang predicts nothing about price.</td></tr><tr><td><strong>I — Identity and Online Safety</strong> (p. 16)</td><td>Protect private information; a public nickname does not justify revealing credentials.</td><td>“A stranger asks for a password to verify your account. Share it or refuse?” <strong>Refuse.</strong> Verification claims do not make a secret safe to share.</td></tr><tr><td><strong>J — Jupiter (JUP)</strong> (p. 17)</td><td>The book gives a named Solana swap service as an example, not a tool learners need to use.</td><td>“Is Jupiter in this chapter a required step for the player?” <strong>No.</strong> It is an informational example; the game has no live swap.</td></tr><tr><td><strong>Q — QR Codes in Web3</strong> (p. 24)</td><td>A QR code may lead to a site or app; its appearance does not verify the destination.</td><td>“A random poster&#39;s code promises a prize. Scan or check its source first?” <strong>Check first.</strong> Codes can hide an unsafe link. No real scanning is needed in play.</td></tr><tr><td><strong>R — Risks, Red Flags &amp; Staying Scam-Safe</strong> (p. 25)</td><td>Urgency, impossible rewards, suspicious links and requests for secrets are warning signs.</td><td>“A message demands a secret to claim free coins in one minute. Trust or reject?” <strong>Reject.</strong> The deadline and secret request are red flags.</td></tr><tr><td><strong>U — Understanding Web3 Safety</strong> (p. 28)</td><td>Pause, verify independently and seek trusted help before acting.</td><td>“You cannot verify a new wallet link. Proceed or ask a trusted adult/guide?” <strong>Ask.</strong> Uncertainty is a reason to pause.</td></tr><tr><td><strong>V — Volatility (What It Means)</strong> (p. 29)</td><td>The price of an asset may change rapidly; future value is uncertain.</td><td>“A coin rose yesterday. Is tomorrow&#39;s price guaranteed?” <strong>No.</strong> Past movement does not guarantee a new price.</td></tr><tr><td><strong>W — Wallets (Read-Only Awareness)</strong> (p. 30)</td><td>A wallet helps a user manage access and transactions; secret recovery information must stay private.</td><td>“Does a wallet screen mean coins are physically stored in the phone?” <strong>No.</strong> The interface helps access a network account; no real wallet is used.</td></tr><tr><td><strong>X — XRP</strong> (p. 31)</td><td>A named cryptocurrency example; recognition does not imply endorsement or a lesson in buying it.</td><td>“Is XRP a type of government-issued fiat currency?” <strong>No.</strong> It is a named cryptocurrency example in the book.</td></tr></tbody></table><h2 id="original-source-terms-blockchain-primary-world-1313">Original source terms: Blockchain primary world (13/13)<a class="header-anchor" href="#original-source-terms-blockchain-primary-world-1313" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Letter / source</th><th>Teaching point</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td><strong>B — Blockchain</strong> (PDF p. 9)</td><td>A chain organizes records into linked blocks shared under network rules; tampering can be detected under stated assumptions.</td><td>“The local copy shows price 6, but trusted receipt shows 8. Which needs investigation?” <strong>The local copy.</strong> A disagreement signals checking, not automatic proof of what happened.</td></tr><tr><td><strong>D — Decentralization</strong> (p. 11)</td><td>Control or recordkeeping is distributed among participants rather than one operator.</td><td>“Are three screenshots on one phone three independent participants?” <strong>No.</strong> Copies on one device do not create distributed control.</td></tr><tr><td><strong>G — Gas Fees</strong> (p. 14)</td><td>Some blockchain actions require a network-use fee separate from an item&#39;s price; fees vary by network and load.</td><td>“Lantern price 8, fee 1. Is the fee part of the item&#39;s listed price?” <strong>No.</strong> It is a separate transaction cost.</td></tr><tr><td><strong>K — Keys (Public &amp; Private)</strong> (p. 18)</td><td>Public receiving information may be shared; private signing/access information must be protected.</td><td>“Which may be shared in the fictional example: receiving address or private key?” <strong>Receiving address.</strong> The private key controls access.</td></tr><tr><td><strong>L — Ledger</strong> (p. 19)</td><td>A ledger records transactions; compare a record with an accepted reference before deciding which copy to use.</td><td>“The reference says 8; a display says 6. Accept 6 without checking?” <strong>No.</strong> Inspect the discrepancy first.</td></tr><tr><td><strong>M — Mining &amp; Validators</strong> (p. 20)</td><td>Different networks use different participants and methods to propose/check blocks; miners and validators are not universal interchangeable roles.</td><td>“Must every blockchain have both miners and validators doing the same job?” <strong>No.</strong> The network&#39;s design determines roles.</td></tr><tr><td><strong>N — NFTs (Non-Fungible Tokens)</strong> (p. 21)</td><td>A unique token record can indicate ownership of a specific token; that alone does not establish value, copyright or ownership of an underlying file.</td><td>“Lantern #014 has a unique token record. Does that guarantee resale value?” <strong>No.</strong> Uniqueness and market value differ.</td></tr><tr><td><strong>O — On-Chain vs Off-Chain</strong> (p. 22; printed locator <code>0/15</code>)</td><td>An on-chain action changes the shared ledger; an off-chain action occurs elsewhere.</td><td>“A private note in the game journal appears only on this phone. Is it on-chain?” <strong>No.</strong> A local note is not a shared blockchain record.</td></tr><tr><td><strong>P — Proof Systems</strong> (p. 23)</td><td>Proof of Work and Proof of Stake are different ways networks select/check block additions; neither is a classroom vote.</td><td>“Does the player&#39;s tap alone establish network consensus?” <strong>No.</strong> The card activity represents rules; it is not a live network.</td></tr><tr><td><strong>S — Smart Contracts</strong> (p. 26)</td><td>A deployed program follows coded conditions when given relevant inputs; a classroom if/then example is an analogy.</td><td>“A rule releases a lantern after a confirmed payment. Without that input, should it release?” <strong>No.</strong> The stated condition has not been met.</td></tr><tr><td><strong>T — Tokens (Not Toys!)</strong> (p. 27)</td><td>A token can represent a digital unit, access right or item; it is not automatically real-world money.</td><td>“Does every game token have cash value?” <strong>No.</strong> Its purpose and rights depend on the system.</td></tr><tr><td><strong>Y — Your Data and Privacy in Web3</strong> (p. 32)</td><td>Public records and addresses can expose activity; pseudonyms are not a promise of anonymity.</td><td>“A public address has no printed name. Is its activity necessarily private?” <strong>No.</strong> Public activity may still be observed or linked.</td></tr><tr><td><strong>Z — Zero-Knowledge Proofs</strong> (p. 33)</td><td>Some protocols can prove a claim without exposing the underlying detail; the age example is conceptual.</td><td>“Could a proof show ‘old enough’ without showing the exact birthday?” <strong>Yes, in a suitable system.</strong> The game illustrates the idea; it does not implement a cryptographic proof.</td></tr></tbody></table><p><strong>Book support outside A–Z:</strong> The glossary on PDF p. 35 defines block, node, consensus, seed phrase and related terms. The scam and digital citizenship guidance on pp. 36–38 supports safety feedback. Opening remarks on pp. 2–7 and closing/credits on pp. 39–43 provide purpose and attribution, not more letter lessons. The source explicitly frames exchanges and wallets as awareness topics and does not teach trading or investing.</p><h2 id="added-ai-terms-13-paired-letter-slots">Added AI terms: 13 paired letter slots<a class="header-anchor" href="#added-ai-terms-13-paired-letter-slots" aria-label="Link to this section">​</a></h2><p>These terms are <strong>not from the Web3 encyclopedia</strong>. They were selected at a fundamental level using the primary references linked in each row. The original term in the same letter remains in its Web3 or Blockchain world. The check is draft game copy; the link supports the term and accuracy, not the invented fictional example.</p><table><thead><tr><th>Paired letter / AI term</th><th>Teaching point and source</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td><strong>A — Artificial intelligence</strong></td><td>A task-focused system can infer predictions, recommendations, decisions or content from inputs. <a href="https://oecd.ai/en/wonk/definition">OECD AI system definition</a></td><td>“A fixed ‘if price is 8, display 8’ rule and a helper predicting a request category: which is the AI example?” <strong>The predictor.</strong> A fixed display rule does not learn or infer from examples.</td></tr><tr><td><strong>B — Bias</strong></td><td>Missing or skewed examples can produce systematically uneven outcomes. <a href="https://developers.google.com/machine-learning/crash-course/fairness/types-of-bias">Google: types of bias</a></td><td>“All training cards show daytime requests; the bot often misreads night requests. What should be checked?” <strong>Missing night examples.</strong> More of the same daytime cards may not fix the gap.</td></tr><tr><td><strong>C — Classification</strong></td><td>A classifier predicts one category from input features. <a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google: what is ML?</a></td><td>“The bot marks a request Routine or Review. Is that classification or image generation?” <strong>Classification.</strong> It chooses between defined categories.</td></tr><tr><td><strong>D — Dataset</strong></td><td>A dataset is a collection of examples; coverage and quality matter. <a href="https://developers.google.com/machine-learning/crash-course/overfitting/data-characteristics">Google: data characteristics</a></td><td>“Are three copies of one request as useful as three different relevant cases?” <strong>No.</strong> Copies do not increase the range of cases.</td></tr><tr><td><strong>F — Feature</strong></td><td>A feature is an input detail used for a prediction. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“To review a delivery request, which field matters more: destination mismatch or card color?” <strong>Destination mismatch.</strong> It bears on the decision; color does not in this example.</td></tr><tr><td><strong>G — Generative AI</strong></td><td>Generative models can create new text, images or other content; generated answers need verification. <a href="https://developers.google.com/machine-learning/glossary/generative">Google: generative glossary</a></td><td>“An authored ‘AI answer’ says fee 2, while the receipt says fee 1. Trust the answer or the receipt?” <strong>Receipt.</strong> Plausible text can conflict with evidence. Label the game example as scripted.</td></tr><tr><td><strong>H — Human oversight</strong></td><td>People should retain agency and check consequential AI suggestions. <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a></td><td>“The helper suggests dispatch despite a missing address. Auto-send or pause for a person to check?” <strong>Pause.</strong> Missing evidence needs human judgment.</td></tr><tr><td><strong>L — Label</strong></td><td>A label is the known target answer attached to a training example. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“A past request is marked Review. Is ‘Review’ its label or its destination?” <strong>Label.</strong> It is the known category supplied with the example.</td></tr><tr><td><strong>M — Model</strong></td><td>A trained model uses learned patterns to infer an output for a new input. <a href="https://developers.google.com/machine-learning/glossary/fundamentals">Google: ML glossary</a></td><td>“If the bot repeats a fixed list of authored replies regardless of examples, has the player trained a model?” <strong>No.</strong> The replies must depend on training examples for that claim.</td></tr><tr><td><strong>P — Prediction</strong></td><td>A prediction is a model&#39;s proposed output, which can be wrong. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“The bot predicts Routine, but the verified case is Review. Which is ground truth here?” <strong>The verified case.</strong> A prediction is a claim to check.</td></tr><tr><td><strong>R — Responsible AI</strong></td><td>Consider intended use, privacy, possible harm, fairness and human control. <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a>; <a href="https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/">NIST AI RMF characteristics</a></td><td>“Should real learner identities be placed in a practice dataset when fictional examples suffice?” <strong>No.</strong> Use the minimum data needed for the learning activity.</td></tr><tr><td><strong>T — Training</strong></td><td>A model changes or fits from examples during training; showing a scripted answer is different. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“After correcting a training label, the model&#39;s later output changes. What likely influenced it?” <strong>The corrected example.</strong> Verify with a fresh case; one change is not broad reliability.</td></tr><tr><td><strong>V — Validation</strong></td><td>Check a model on examples separate from training; keep final test cases untouched. <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google: dividing datasets</a></td><td>“The bot gets every memorized training card right. Is that enough to claim it works on new cards?” <strong>No.</strong> Try unseen cases and inspect errors.</td></tr></tbody></table><p><strong>AI activity boundary:</strong> The simplified GDD&#39;s label-and-check round can demonstrate these ideas as a clearly named simulation. A genuine tiny offline classifier is the current conditional A01–A03 stretch and needs example-dependent fitting plus fresh test cases. Do not present authored branches as training, generative output or an autonomous agent. See <a href="https://ai4k12.org/gradeband-progression-charts/">AI4K12 grade-band progression</a> and <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO&#39;s AI Competency Framework for Students</a> for age-level and human agency review.</p><h2 id="direct-comparison-with-the-simplified-gdd">Direct comparison with the simplified GDD<a class="header-anchor" href="#direct-comparison-with-the-simplified-gdd" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Question for owner review</th><th>This source pack</th><th>Simplified GDD proposal</th><th>Decision needed</th></tr></thead><tbody><tr><td>How many source terms exist?</td><td>26 unchanged book terms plus 13 added AI terms; 39 term checks.</td><td>Three worlds, each with three beats and one final review.</td><td>Decide whether all 39 receive taught lessons in the shipped version or some remain encyclopedia references/later content.</td></tr><tr><td>How are terms taught?</td><td>Recommended 15 prerequisite-ordered clusters, with one bounded mini-game per world and a fresh check per cluster.</td><td>Three 8–12 minute worlds, one quest and mini-game each.</td><td>Choose chapter depth and total playtime; do not label 15 clusters as three short worlds without testing.</td></tr><tr><td>What is the world story?</td><td>One fictional transaction supplies examples; record checking follows; AI advice is checked against evidence.</td><td>Safe connection terminal, damaged record display, helper bot.</td><td>Align the shared fictional receipt and station language in final lesson scripts.</td></tr><tr><td>What is assessed?</td><td>A check for each term is available as draft source material, plus suggested cluster checks.</td><td>One new final review item per world.</td><td>Pick a small representative set for the first build; later checks can support recall and transfer. A correct quiz response is not proof of mastery.</td></tr><tr><td>What is interactive?</td><td>Web3 safety sort; Blockchain linked-record comparison; AI label/feature/prediction round.</td><td>The same three subject mini-games at world scale.</td><td>Decide whether the AI round is a scripted simulation or an actual fitted model.</td></tr><tr><td>What is the delivery boundary?</td><td>Complete content inventory for planning, with no promise to implement every row.</td><td>Proposed replacement first version; not yet canonical.</td><td>Keep November 10 core and November 21 pre-final gates visible; protect integration, phone QA, manuscript and rehearsal.</td></tr></tbody></table><p><strong>Recommended smallest workable first pass:</strong> retain the complete A–Z and AI inventory as reference content, build the three simplified world activities and teach only the terms needed to understand those actions, then add grouped lesson checks in prerequisite order as capacity and learner testing permit. The owner should explicitly choose whether this supersedes the earlier “one lesson per original letter” direction. No term is deleted by grouping; its lesson depth and delivery date are the open decisions.</p><h2 id="editorial-completion-checklist">Editorial completion checklist<a class="header-anchor" href="#editorial-completion-checklist" aria-label="Link to this section">​</a></h2><p>Before Sean turns these seeds into production content, confirm for every shipped lesson: (1) one age-appropriate objective, (2) exact screen/dialogue copy, (3) fictional evidence visible before the choice, (4) correct and plausible wrong responses, (5) reasoned feedback and retry, (6) a fresh transfer item, (7) review of security/financial/AI accuracy, and (8) content ID and version for saved progress. Educator review and a short playtest should examine reading load and whether a learner can explain the reasoning, not just tap the expected button. These steps are pending; this pack does not assert validation or learning gains.</p></div>',1)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
